const source = $json.body ?? $json;
if (!source.missionId || !source.taskId || !source.actorInput || !source.callbackUrl) {
  throw new Error('missionId, taskId, actorInput e callbackUrl são obrigatórios.');
}
return [{ json: {
  missionId: String(source.missionId),
  playbook: String(source.playbook || ''),
  taskId: String(source.taskId),
  actorInput: source.actorInput,
  callbackUrl: String(source.callbackUrl)
} }];

const source = $json;
const input = source.actorInput ?? {};
if (source.playbook !== 'b2b_prospecting') return [{ json: source }];

const keywords = [...new Set((input.keywords ?? []).map((value) => String(value).trim()).filter(Boolean))].slice(0, 10);
const regions = [...new Set((input.regions ?? []).map((value) => String(value).trim()).filter(Boolean))];
if (!keywords.length) throw new Error('A prospecção B2B precisa de ao menos um setor ou termo de busca.');
if (regions.length !== 1) throw new Error('A prospecção B2B precisa de exatamente uma região por missão.');

const requested = Number(input.maxItems ?? 100);
const maxItems = Math.min(500, Math.max(1, Number.isFinite(requested) ? Math.trunc(requested) : 100));
const perSearch = Math.max(1, Math.ceil(maxItems / keywords.length));

return [{ json: {
  ...source,
  requestedMaxItems: maxItems,
  actorInput: {
    searchStringsArray: keywords,
    locationQuery: regions[0],
    maxCrawledPlacesPerSearch: perSearch,
    language: 'pt-BR',
    skipClosedPlaces: true,
    scrapePlaceDetailPage: false,
    maximumLeadsEnrichmentRecords: 0,
    enableCompetitorAnalysis: false,
    maxCompetitorsToAnalyze: 0,
    scrapeSocialMediaProfiles: {
      facebooks: false,
      instagrams: false,
      youtubes: false,
      tiktoks: false,
      twitters: false
    }
  }
} }];

const source = $('Adapt Playbook Input').first().json;
const incoming = $input.all().map((item) => item.json);

const failure = incoming.find((item) =>
  item &&
  typeof item === 'object' &&
  (item.error?.message || Number(item.statusCode || 0) >= 400)
);

if (failure) {
  const message = failure.error?.message || failure.message || `Apify respondeu ${failure.statusCode}.`;
  return [{
    json: {
      callbackUrl: source.callbackUrl,
      callbackBody: {
        status: 'failed',
        error: String(message).slice(0, 2000)
      }
    }
  }];
}

const flattened = incoming.flatMap((item) => {
  if (Array.isArray(item)) return item;
  if (Array.isArray(item?.data)) return item.data;
  return item && typeof item === 'object' ? [item] : [];
});

const seen = new Set();
const rawItems = flattened.filter((item) => {
  if (!item || typeof item !== 'object' || item.error) return false;
  const key = String(item.url || `${item.title || ''}|${item.street || ''}`).trim().toLowerCase();
  if (!key || seen.has(key)) return false;
  seen.add(key);
  return true;
}).slice(0, Number(source.requestedMaxItems || flattened.length || 100));

let items = rawItems;

if (source.playbook === 'b2b_prospecting') {
  items = rawItems.map((item, index) => {
    const phone = String(item.phone || '').trim();
    const website = String(item.website || '').trim();
    const rating = Number(item.totalScore || 0);
    const reviewsCount = Number(item.reviewsCount || 0);
    const qualityScore =
      (phone ? 30 : 0) +
      (website ? 25 : 0) +
      (item.street ? 15 : 0) +
      (reviewsCount > 0 ? 10 : 0) +
      (item.categoryName ? 10 : 0) +
      (rating > 0 ? 10 : 0);

    return {
      source: 'google_maps',
      position: index + 1,
      businessName: String(item.title || ''),
      category: String(item.categoryName || ''),
      categories: Array.isArray(item.categories) ? item.categories : [],
      rating,
      reviewsCount,
      address: String(item.street || ''),
      city: String(item.city || ''),
      state: String(item.state || ''),
      countryCode: String(item.countryCode || ''),
      phone,
      website,
      mapsUrl: String(item.url || ''),
      contactAvailable: Boolean(phone || website),
      qualityScore
    };
  });
}

return [{
  json: {
    callbackUrl: source.callbackUrl,
    callbackBody: {
      status: 'completed',
      resultCount: items.length,
      resultPreview: items.slice(0, 100)
    }
  }
}];
